      var fs = wx.getFileSystemManager();
      var folder = "".concat(wx.env.USER_DATA_PATH);
      var savePath = "".concat(folder, "/").concat(filename);
      try {
        fs.mkdirSync(folder, true);
      } catch (e) {
        console.log('创建目录:', e);
      }
      uni.showLoading({
        title: '下载中...',
        mask: true
      });
